import type { Ref } from "react";
import { styled } from "styled-components";

import { slideScaleIn } from "@/shared/animations/motion.keyframes";
import type { IdServiceDeLaMarque } from "@/shared/config/services-de-la-marque";
import { withOpacity } from "@/shared/design-tokens/color";
import { nuit } from "@/shared/design-tokens/vitrine-de-nuit.tokens";
import { px, shadow } from "@/shared/design-tokens/scale";
import { radius } from "@/shared/design-tokens/spacing";
import { vitrine } from "@/shared/design-tokens/vitrine-typo";

import { CONTENU_DES_SERVICES } from "./systeme.contenu";

/*
 * Les fiches du survol — chargées à la première INTENTION (survol ou focus
 * d'un service), avec leurs textes, et non avec le héros : elles ne servent
 * qu'au survol, et le premier écran tirait deux fichiers de plus que son
 * plafond (mesuré le 2026-09-25). L'horloge les place à côté du service
 * (`useAnimationDuReseau`, par la poignée `ref`).
 */

/**
 * Les trois fiches d'un service survolé, posées à côté de lui — sur un verre :
 * sans fond, elles se posaient à même le disque d'un voisin (vu au navigateur
 * le 2026-09-25).
 */
const Fiches = styled.ul`
  position: absolute;
  left: 0;
  top: 0;
  z-index: 45;
  display: flex;
  flex-direction: column;
  gap: ${px(6)};
  margin: 0;
  padding: ${px(10)} ${px(14)};
  border: var(--border-thin) solid ${withOpacity(nuit.accent, 0.28)};
  border-radius: ${radius.md};
  background:
    linear-gradient(${nuit.verre}, ${nuit.verreBas}),
    ${withOpacity(nuit.fond, 0.9)};
  backdrop-filter: blur(${px(8)});
  box-shadow: ${shadow(`0 10px 28px ${withOpacity(nuit.ombrePortee, 0.45)}`)};
  list-style: none;
  pointer-events: none;
  transform: translate3d(-9999px, -9999px, 0);

  li {
    display: flex;
    align-items: center;
    gap: ${px(8)};
    font-size: ${vitrine.caption};
    line-height: 1.3;
    color: ${nuit.encreSurLaScene};
    white-space: nowrap;
    text-shadow: 0 0 ${px(8)} ${nuit.fond};
    animation: ${slideScaleIn(4, 0.98)} 0.28s cubic-bezier(0.16, 1, 0.3, 1) both;
  }

  li:nth-child(2) {
    animation-delay: 0.05s;
  }

  li:nth-child(3) {
    animation-delay: 0.1s;
  }

  li::before {
    content: "";
    width: ${px(14)};
    height: var(--border-thin);
    background: ${withOpacity(nuit.accent, 0.7)};
  }

  &[data-cote="gauche"] li {
    flex-direction: row-reverse;
  }

  @media (prefers-reduced-motion: reduce) {
    li {
      animation: none;
    }
  }
`;

export default function FichesDuSurvol({
  id,
  ref,
}: {
  id: IdServiceDeLaMarque;
  ref?: Ref<HTMLUListElement>;
}) {
  return (
    <Fiches ref={ref} aria-hidden="true">
      {CONTENU_DES_SERVICES[id].fiches.slice(0, 3).map((fiche) => (
        <li key={fiche.id}>{fiche.libelle}</li>
      ))}
    </Fiches>
  );
}
